            [('Límite inferior', '7,1 − 0,5', '7.1-2*0.25', 6.6, 'dimensionless'), ('Límite superior', '7,1 + 0,5', '7.1+2*0.25', 7.6, 'dimensionless'), ('Células dentro', '0,954 × 1000', '0.954*1000', 954, 'dimensionless')],
            'El intervalo es de 6,6 a 7,6 µm y se esperan unas 954 células dentro, es decir, unas 46 fuera.',
